{
  "votes": [
    {
      "item": "i01",
      "choice": "v1",
      "reason": "À la page 4, la résolution 26-06-170 constate l’avis de motion donné par Mona Beaulac pour le règlement 765-26 relativement à l’occupation du domaine public."
    },
    {
      "item": "i02",
      "choice": "v1",
      "reason": "À la page 4, le texte indique expressément « Je dépose et présente le projet de règlement numéro 765-26 », étape distincte de l’avis de motion selon les règles."
    },
    {
      "item": "i03",
      "choice": "v1",
      "reason": "À la page 9, la résolution 26-06-177 accorde la demande de PIIA pour le remplacement de toiture au 152, Rivière."
    },
    {
      "item": "i04",
      "choice": "v1",
      "reason": "À la page 9, la résolution 26-06-178 accorde le PIIA de la nouvelle proposition de quatre logements sur le lot 5 603 254, tandis que le refus initial est seulement historique."
    },
    {
      "item": "i05",
      "choice": "v1",
      "reason": "À la page 9, la résolution 26-06-179 accorde la dérogation permettant un stationnement à moins de 60 centimètres de la limite droite au 125, rue Alcée-Rocheleau."
    },
    {
      "item": "i06",
      "choice": "v1",
      "reason": "À la page 9, la résolution 26-06-179 accorde également la dérogation de stationnement concernant la limite gauche du 137, rue Alcée-Rocheleau, objet foncier explicitement distinct."
    },
    {
      "item": "i07",
      "choice": "v1",
      "reason": "À la page 10, la résolution 26-06-180 accepte la dérogation mineure pour une construction neuve à 5.68 mètres de la ligne avant au 180, rue du Parc."
    },
    {
      "item": "i08",
      "choice": "v1",
      "reason": "À la page 10, la résolution 26-06-181 refuse l’aménagement du développement des Cerfs dans le cadre d’un avis préliminaire assujetti au règlement sur les PIIA, conformément à la règle voulant qu’un refus reste un refus."
    },
    {
      "item": "i09",
      "choice": "v1",
      "reason": "À la page 11, la résolution adoptée 26-06-182 autorise l’installation d’une terrasse sur une portion du parc Dr. Adrien Tougas, avec retrait obligatoire avant le 19 octobre 2026."
    },
    {
      "item": "i10",
      "choice": "v2",
      "reason": "À la page 11, la résolution 26-06-183 autorise la signature de l’addenda au bail du local #105 situé au 52, rue du Pont, acte foncier inclus même pour un usage non résidentiel."
    },
    {
      "item": "i11",
      "choice": "v1",
      "reason": "À la page 15, la résolution 26-06-190 constate l’avis de motion du règlement 702-26-9 modifiant les permis et certificats quant aux amendes relatives à l’abattage d’arbre."
    },
    {
      "item": "i12",
      "choice": "v1",
      "reason": "À la page 15, la résolution 26-06-191 adopte expressément le premier projet du règlement 702-26-9, ce qui atteste l’étape projet_reglement distincte de l’avis de motion."
    }
  ]
}
